// Errors.
var (
	ErrPlanInactive = errors.New("the plan is not active")
	ErrCanceled     = errors.New("the subscription is canceled")
)

// Service runs subscriptions.
type Service struct {
	Store     *store.Store
	Payments  *payments.Service
	Clock     clock.Clock
	Publisher payments.Publisher // nil: no events
}

// CreateInput is a new subscription.
type CreateInput struct {
	CustomerID      string
	PlanID          string
	Quantity        int // 0 means 1
	DiscountPercent int
}

// Create starts a subscription now. With a plan that has a trial, the subscription is trialing until the trial ends, and
// its first period starts then. Otherwise its first period starts now; for a licensed plan that period is invoiced at once
// and charged to the customer's default payment method, if it has one (a declined charge makes the subscription past due).
func (s *Service) Create(ctx context.Context, orgID string, in CreateInput) (store.Subscription, error) {
	plan, ok := s.Store.Plan(orgID, in.PlanID)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	if !plan.Active {
		return store.Subscription{}, ErrPlanInactive
	}
	if in.Quantity == 0 {
		in.Quantity = 1
	}
	now := s.Clock.Now()
	sub := store.Subscription{OrgID: orgID, CustomerID: in.CustomerID, PlanID: plan.ID, Quantity: in.Quantity, DiscountPercent: in.DiscountPercent,
		StartedAt: now, CurrentPeriodStart: now}
	if plan.TrialDays > 0 {
		end := now.AddDate(0, 0, plan.TrialDays)
		sub.Status, sub.TrialEnd, sub.CurrentPeriodEnd = store.Trialing, &end, end
	} else {
		sub.Status, sub.CurrentPeriodEnd = store.Active, billing.AddInterval(now, plan.Interval)
	}
	sub, err := s.Store.CreateSubscription(sub, now)
	if err != nil {
		return store.Subscription{}, err
	}
	s.publish(ctx, orgID, "subscription.created", sub)
	if sub.Status == store.Active && plan.UsageType == store.Licensed {
		paid, err := s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
		if err != nil {
			return sub, err
		}
		if !paid {
			if sub, err = s.setStatus(ctx, sub, store.PastDue); err != nil {
				return sub, err
			}
		}
	}
	return sub, nil
}

// UpdateInput changes a subscription; nil fields stay as they are.
type UpdateInput struct {
	PlanID   *string
	Quantity *int
}

// Update changes a subscription's plan or quantity. The change applies at once and is billed from the next period on.
func (s *Service) Update(ctx context.Context, orgID, id string, in UpdateInput) (store.Subscription, error) {
	if in.PlanID != nil {
		p, ok := s.Store.Plan(orgID, *in.PlanID)
		if !ok {
			return store.Subscription{}, store.ErrNotFound
		}
		if !p.Active {
			return store.Subscription{}, ErrPlanInactive
		}
	}
	sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
		if sub.Status == store.Canceled {
			return ErrCanceled
		}
		if in.PlanID != nil {
			sub.PlanID = *in.PlanID
		}
		if in.Quantity != nil {
			sub.Quantity = *in.Quantity
		}
		return nil
	})
	if err != nil {
		return store.Subscription{}, err
	}
	s.publish(ctx, orgID, "subscription.updated", sub)
	return sub, nil
}

// Cancel cancels a subscription now, or at the end of its current period when atPeriodEnd is set. Canceling a canceled
// subscription changes nothing.
func (s *Service) Cancel(ctx context.Context, orgID, id string, atPeriodEnd bool) (store.Subscription, error) {
	now := s.Clock.Now()
	sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
		if sub.Status == store.Canceled {
			return nil
		}
		if atPeriodEnd {
			sub.CancelAtPeriodEnd = true
			return nil
		}
		sub.Status, sub.CanceledAt = store.Canceled, &now
		return nil
	})
	if err != nil {
		return store.Subscription{}, err
	}
	if sub.Status == store.Canceled {
		s.publish(ctx, orgID, "subscription.canceled", sub)
	} else {
		s.publish(ctx, orgID, "subscription.updated", sub)
	}
	return sub, nil
}

// RenewDue renews every subscription, of every organization, whose current period has ended. A subscription set to cancel
// at the end of its period is canceled. Otherwise its next period starts and is invoiced: a licensed plan bills the new
// period in advance, a metered plan bills the usage of the period that ended. A declined charge makes the subscription past
// due. RenewDue returns how many subscriptions it renewed or canceled.
func (s *Service) RenewDue(ctx context.Context) (int, error) {
}

// Pay charges an open invoice's total to paymentMethod, or to the customer's default payment method when it is empty, and
// marks the invoice paid. An invoice whose total is zero or less is marked paid without a charge. A declined charge is
// recorded as a failed payment and returned as a *DeclineError; when the gateway is unavailable nothing is recorded and the
// error wraps ErrUnavailable.
func (s *Service) Pay(ctx context.Context, orgID, invoiceID, paymentMethod string) (store.Invoice, store.Payment, error) {
	inv, ok := s.Store.Invoice(orgID, invoiceID)
	if !ok {
		return store.Invoice{}, store.Payment{}, store.ErrNotFound
	}
	switch inv.Status {
	case store.InvoicePaid:
		return inv, store.Payment{}, ErrAlreadyPaid
	case store.InvoiceVoid:
		return inv, store.Payment{}, ErrInvoiceVoid
	}
	total := billing.Compute(inv).Total
	if total <= 0 {
		inv, err := s.markPaid(ctx, inv, store.Payment{})
		return inv, store.Payment{}, err
	}
	if paymentMethod == "" {
		if c, ok := s.Store.Customer(orgID, inv.CustomerID); ok {
			paymentMethod = c.DefaultPaymentMethod
		}
	}
	if paymentMethod == "" {
		return inv, store.Payment{}, ErrNoPaymentMethod
	}
	res, err := s.Gateway.Charge(ctx, ChargeRequest{Amount: total, Currency: inv.Currency, PaymentMethod: paymentMethod, Description: "Invoice " + inv.ID})
	var decline *DeclineError
	switch {
	case errors.As(err, &decline):
		p, perr := s.Store.CreatePayment(store.Payment{OrgID: orgID, InvoiceID: inv.ID, Amount: total, Currency: inv.Currency, Status: store.PaymentFailed, FailureCode: decline.Code}, s.Clock.Now())
		if perr != nil {
			return inv, store.Payment{}, perr
		}
		s.publish(ctx, orgID, "invoice.payment_failed", map[string]any{"invoice_id": inv.ID, "payment_id": p.ID, "failure_code": decline.Code})
		return inv, p, err
	case err != nil:
		if errors.Is(err, ErrUnavailable) {
			return inv, store.Payment{}, err
		}
		return inv, store.Payment{}, fmt.Errorf("%w: %v", ErrUnavailable, err)
	}
	p, err := s.Store.CreatePayment(store.Payment{OrgID: orgID, InvoiceID: inv.ID, Amount: total, Currency: inv.Currency, Status: store.PaymentSucceeded, GatewayRef: res.Ref}, s.Clock.Now())
	if err != nil {
		return inv, store.Payment{}, err
	}
	inv, err = s.markPaid(ctx, inv, p)
	return inv, p, err
}

func (s *Service) markPaid(ctx context.Context, inv store.Invoice, p store.Payment) (store.Invoice, error) {
	now := s.Clock.Now()
	inv, err := s.Store.UpdateInvoice(inv.OrgID, inv.ID, func(i *store.Invoice) error {
		i.Status = store.InvoicePaid
		i.PaidAt = &now
		return nil
	})
	if err != nil {
		return store.Invoice{}, err
	}
	s.publish(ctx, inv.OrgID, "invoice.paid", map[string]any{"invoice_id": inv.ID, "payment_id": p.ID, "amount": p.Amount, "currency": inv.Currency})
	return inv, nil
}

func (s *Service) publish(ctx context.Context, orgID, typ string, data any) {
	if s.Publisher != nil {
		_ = s.Publisher.Publish(ctx, orgID, typ, data)
	}
}
		st = f.State
	default:
		return nil, fmt.Errorf("snapshot %s: %w %d", path, ErrUnsupportedVersion, head.Version)
	}
	return store.FromState(st)
}

// Version 1 (Tally 0.x) kept the state at the top level. Organizations had no plan or time zone, customers had a
// full_name, and plans had a price in US cents (price_cents) and were all licensed.
type fileV1 struct {
	Seq           int                  `json:"seq"`
	Orgs          []orgV1              `json:"orgs"`
	Users         []store.User         `json:"users"`
	Members       []store.Member       `json:"members"`
	APIKeys       []store.APIKey       `json:"api_keys"`
	Customers     []customerV1         `json:"customers"`
	Plans         []planV1             `json:"plans"`
	Subscriptions []store.Subscription `json:"subscriptions"`
	Invoices      []store.Invoice      `json:"invoices"`
	Payments      []store.Payment      `json:"payments"`
}

type orgV1 struct {
	ID        string    `json:"id"`
	Name      string    `json:"name"`
	TaxRateBP int       `json:"tax_rate_bp"`
	CreatedAt time.Time `json:"created_at"`
}

type customerV1 struct {
	ID        string    `json:"id"`
	OrgID     string    `json:"org_id"`
	FullName  string    `json:"full_name"`
	Email     string    `json:"email"`
	CreatedAt time.Time `json:"created_at"`
}

type planV1 struct {
	ID         string         `json:"id"`
	OrgID      string         `json:"org_id"`
	Name       string         `json:"name"`
	PriceCents int64          `json:"price_cents"`
	Interval   store.Interval `json:"interval"`
	TrialDays  int            `json:"trial_days"`
	CreatedAt  time.Time      `json:"created_at"`
}

func migrateV1(b []byte) (store.State, error) {
	var f fileV1
	if err := json.Unmarshal(b, &f); err != nil {
		return store.State{}, err
	}
	st := store.State{Seq: f.Seq, Users: f.Users, Members: f.Members, APIKeys: f.APIKeys, Subscriptions: f.Subscriptions, Invoices: f.Invoices, Payments: f.Payments}
	for _, o := range f.Orgs {
		st.Orgs = append(st.Orgs, store.Org{ID: o.ID, Name: o.Name, Plan: store.OrgFree, TimeZone: "UTC", TaxRateBP: o.TaxRateBP, CreatedAt: o.CreatedAt})
	}
	for _, c := range f.Customers {
		st.Customers = append(st.Customers, store.Customer{ID: c.ID, OrgID: c.OrgID, Name: c.FullName, Email: c.Email, CreatedAt: c.CreatedAt})
	}
	for _, p := range f.Plans {
		st.Plans = append(st.Plans, store.Plan{ID: p.ID, OrgID: p.OrgID, Name: p.Name, Currency: money.USD, UnitAmount: p.PriceCents, Interval: p.Interval,
			UsageType: store.Licensed, TrialDays: p.TrialDays, Active: true, CreatedAt: p.CreatedAt})
	}
	return st, nil
}

