	if !ok {
		return
	}
	q := r.URL.Query()
	es := s.store.AuditEntries(p.OrgID, store.AuditFilter{Action: q.Get("action"), TargetID: q.Get("target_id"), ActorID: q.Get("actor_id")})
	slices.Reverse(es)
	items, next := pageOfNewest(es, auditKey, pg)
	views := make([]auditView, 0, len(items))
	for _, e := range items {
		views = append(views, viewAudit(e))
	}
	writeJSON(w, http.StatusOK, list{Items: views, NextCursor: next})
}
EOF
cat >> internal/api/respond.go <<'EOF'

// pageOfNewest is pageOf for items sorted newest first: the next page holds the items after the cursor's position, which
// are older.
func pageOfNewest[T any](items []T, key func(T) cursor, p page) ([]T, string) {
	start := 0
	if p.after != nil {
		start = len(items)
		for i, it := range items {
			if key(it).less(*p.after) {
				start = i
				break
			}
		}
	}
	end := min(start+p.limit, len(items))
	out := items[start:end]
	next := ""
	if end < len(items) && len(out) > 0 {
		next = encodeCursor(key(out[len(out)-1]))
	}
	return out, next
}
